pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(uint256 fuzzedSeed) public {
        string memory result = c.version();
        bytes memory resultBytes = bytes(result);
        assertTrue(resultBytes[0] == '1' && resultBytes[1] == '.' && resultBytes[2] == '0' && resultBytes[3] == '.' && resultBytes[4] == '0');
    }
}
